-- Entasis Academy, migration 9 : schemas et figures des decks (brouillons).
--
-- Genere par scripts/academy/generer-decks.mjs depuis scripts/academy/decks/*.json :
-- ne pas editer a la main, regenerer. Complete le brouillon courant d un
-- module deja seme par la migration 7 : pose les schemas de la version
-- (remplacement par cle, les autres cles conservees), pose payload.figure
-- sur les exercices existants reperes par (ordre, type) qui n en ont pas
-- encore, insere les exercices nouveaux (ordre au dela du maximum existant)
-- avec leur corrige, ordre et association deja melanges. Idempotent. Une
-- version publiee n est jamais touchee : sans brouillon, raise notice et
-- rien. A appliquer apres la migration 8 (colonne academy_module_versions.schemas).

-- ── Schemas : Fiscalité : raisonner avant de proposer (fiscalite-raisonner) ──
do $schemas_fiscalite_raisonner$
declare v_mod uuid; v_ver uuid; v_max integer; v_item uuid; v_nouveaux jsonb; v_conserves jsonb;
begin
  select id into v_mod from public.academy_modules where slug = $academy_deck$fiscalite-raisonner$academy_deck$;
  if v_mod is null then
    raise notice 'academy_9_schemas : module % absent, rien a faire (semer la migration 7 d abord)', $academy_deck$fiscalite-raisonner$academy_deck$;
    return;
  end if;
  select id into v_ver from public.academy_module_versions where module_id = v_mod and statut = 'brouillon' order by numero desc limit 1;
  if v_ver is null then
    raise notice 'academy_9_schemas : aucun brouillon pour %, rien a faire (une version publiee ne se modifie pas)', $academy_deck$fiscalite-raisonner$academy_deck$;
    return;
  end if;
  -- Schemas de la version : les cles du deck remplacent les leurs, les autres restent.
  v_nouveaux := $academy_deck$[{"cle":"colonne_impot","titre":"Déduction, réduction, crédit : où chacun agit","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 360\" font-family=\"system-ui, -apple-system, Segoe UI, sans-serif\"><title>Déduction, réduction, crédit : où chacun agit</title><rect x=\"0\" y=\"0\" width=\"640\" height=\"360\" fill=\"#FFFFFF\"/><text x=\"320\" y=\"34\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"600\" fill=\"#162443\">Déduction, réduction, crédit : où chacun agit</text><rect x=\"24\" y=\"58\" width=\"180\" height=\"40\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"114\" y=\"83\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">Revenu déclaré</text><line x1=\"114\" y1=\"98\" x2=\"114\" y2=\"108\" stroke=\"#C5A55A\" stroke-width=\"2\"/><polygon points=\"107,106 114,118 121,106\" fill=\"#C5A55A\"/><rect x=\"24\" y=\"118\" width=\"180\" height=\"40\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"114\" y=\"143\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">Revenu imposable</text><line x1=\"114\" y1=\"158\" x2=\"114\" y2=\"168\" stroke=\"#C5A55A\" stroke-width=\"2\"/><polygon points=\"107,166 114,178 121,166\" fill=\"#C5A55A\"/><rect x=\"24\" y=\"178\" width=\"180\" height=\"40\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"114\" y=\"203\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">Impôt calculé</text><line x1=\"114\" y1=\"218\" x2=\"114\" y2=\"228\" stroke=\"#C5A55A\" stroke-width=\"2\"/><polygon points=\"107,226 114,238 121,226\" fill=\"#C5A55A\"/><rect x=\"24\" y=\"238\" width=\"180\" height=\"40\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"114\" y=\"263\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">Impôt à payer</text><line x1=\"126\" y1=\"108\" x2=\"230\" y2=\"108\" stroke=\"#C5A55A\" stroke-width=\"2\"/><rect x=\"230\" y=\"62\" width=\"386\" height=\"74\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\"/><text x=\"423\" y=\"82\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">Déduction</text><text x=\"423\" y=\"100\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Retirée du revenu, avant le calcul de l’impôt</text><text x=\"423\" y=\"116\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Revenu imposable = revenu déclaré moins les déductions</text><text x=\"423\" y=\"132\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Le barème s’applique au revenu diminué</text><line x1=\"126\" y1=\"168\" x2=\"230\" y2=\"168\" stroke=\"#8A95A8\" stroke-width=\"2\"/><rect x=\"230\" y=\"140\" width=\"386\" height=\"56\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><text x=\"423\" y=\"158\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">Barème progressif</text><text x=\"423\" y=\"175\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">0, 11, 30, 41 et 45 %, tranche par tranche</text><text x=\"423\" y=\"191\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Seuils indexés chaque année</text><line x1=\"126\" y1=\"228\" x2=\"230\" y2=\"228\" stroke=\"#C5A55A\" stroke-width=\"2\"/><rect x=\"230\" y=\"200\" width=\"386\" height=\"56\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\"/><text x=\"423\" y=\"218\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">Réduction et crédit</text><text x=\"423\" y=\"235\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Imputés sur l’impôt calculé, après le barème</text><text x=\"423\" y=\"251\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Surplus : réduction perdue, crédit remboursé au delà de 8 €</text><text x=\"24\" y=\"294\" font-size=\"13\" fill=\"#8A95A8\">Ce que chacun vaut pour le client</text><rect x=\"24\" y=\"302\" width=\"190\" height=\"50\" rx=\"8\" fill=\"#F5EDD8\"/><text x=\"119\" y=\"322\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#162443\">Déduction</text><text x=\"119\" y=\"341\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">vaut la tranche du client</text><rect x=\"225\" y=\"302\" width=\"190\" height=\"50\" rx=\"8\" fill=\"#F5EDD8\"/><text x=\"320\" y=\"322\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#162443\">Réduction</text><text x=\"320\" y=\"341\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">au plus l’impôt dû</text><rect x=\"426\" y=\"302\" width=\"190\" height=\"50\" rx=\"8\" fill=\"#F5EDD8\"/><text x=\"521\" y=\"322\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#162443\">Crédit</text><text x=\"521\" y=\"341\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">sa valeur faciale</text></svg>","legende":"La déduction agit avant le calcul de l’impôt et vaut la tranche du client ; réduction et crédit s’imputent après, sur l’impôt calculé. Seul le surplus d’un crédit est remboursé."},{"cle":"tranche_marginale","titre":"Une déduction vaut la tranche marginale","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 360\" font-family=\"system-ui, -apple-system, Segoe UI, sans-serif\"><title>Une déduction vaut la tranche marginale</title><rect x=\"0\" y=\"0\" width=\"640\" height=\"360\" fill=\"#FFFFFF\"/><text x=\"320\" y=\"34\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"600\" fill=\"#162443\">Une déduction vaut la tranche marginale</text><rect x=\"12\" y=\"50\" width=\"302\" height=\"240\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><text x=\"163\" y=\"72\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">Cas fictif 1 : dans une seule tranche</text><rect x=\"60\" y=\"86\" width=\"116\" height=\"26\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><rect x=\"60\" y=\"112\" width=\"116\" height=\"48\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><rect x=\"60\" y=\"160\" width=\"116\" height=\"88\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><rect x=\"60\" y=\"248\" width=\"116\" height=\"32\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><text x=\"52\" y=\"103\" text-anchor=\"end\" font-size=\"13\" fill=\"#8A95A8\">45 %</text><text x=\"52\" y=\"140\" text-anchor=\"end\" font-size=\"13\" fill=\"#8A95A8\">41 %</text><text x=\"52\" y=\"208\" text-anchor=\"end\" font-size=\"13\" fill=\"#8A95A8\">30 %</text><text x=\"52\" y=\"268\" text-anchor=\"end\" font-size=\"13\" fill=\"#8A95A8\">11 %</text><rect x=\"64\" y=\"180\" width=\"108\" height=\"64\" fill=\"#C5A55A\"/><line x1=\"60\" y1=\"180\" x2=\"176\" y2=\"180\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"118\" y=\"174\" text-anchor=\"middle\" font-size=\"13\" fill=\"#162443\">revenu imposable</text><text x=\"118\" y=\"217\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#162443\">6 000 € à 30 %</text><text x=\"188\" y=\"110\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">TMI 30 %</text><text x=\"188\" y=\"134\" font-size=\"13\" fill=\"#2C3548\">Le versement reste</text><text x=\"188\" y=\"152\" font-size=\"13\" fill=\"#2C3548\">dans la tranche :</text><text x=\"188\" y=\"176\" font-size=\"13\" fill=\"#2C3548\">6 000 × 30 %</text><text x=\"188\" y=\"200\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">environ 1 800 €</text><rect x=\"326\" y=\"50\" width=\"302\" height=\"240\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><text x=\"477\" y=\"72\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">Cas fictif 2 : sur deux tranches</text><rect x=\"374\" y=\"86\" width=\"116\" height=\"26\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><rect x=\"374\" y=\"112\" width=\"116\" height=\"48\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><rect x=\"374\" y=\"160\" width=\"116\" height=\"88\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><rect x=\"374\" y=\"248\" width=\"116\" height=\"32\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><text x=\"366\" y=\"103\" text-anchor=\"end\" font-size=\"13\" fill=\"#8A95A8\">45 %</text><text x=\"366\" y=\"140\" text-anchor=\"end\" font-size=\"13\" fill=\"#8A95A8\">41 %</text><text x=\"366\" y=\"208\" text-anchor=\"end\" font-size=\"13\" fill=\"#8A95A8\">30 %</text><text x=\"366\" y=\"268\" text-anchor=\"end\" font-size=\"13\" fill=\"#8A95A8\">11 %</text><rect x=\"378\" y=\"138\" width=\"108\" height=\"22\" fill=\"#C5A55A\"/><rect x=\"378\" y=\"160\" width=\"108\" height=\"44\" fill=\"#F5EDD8\"/><line x1=\"374\" y1=\"160\" x2=\"490\" y2=\"160\" stroke=\"#8A95A8\" stroke-width=\"2\"/><line x1=\"374\" y1=\"138\" x2=\"490\" y2=\"138\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"432\" y=\"132\" text-anchor=\"middle\" font-size=\"13\" fill=\"#162443\">revenu imposable</text><text x=\"432\" y=\"154\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#162443\">2 000 € à 41 %</text><text x=\"432\" y=\"187\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#162443\">4 000 € à 30 %</text><text x=\"502\" y=\"110\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">TMI 41 %</text><text x=\"502\" y=\"134\" font-size=\"13\" fill=\"#2C3548\">2 000 € seulement</text><text x=\"502\" y=\"152\" font-size=\"13\" fill=\"#2C3548\">au dessus du seuil :</text><text x=\"502\" y=\"176\" font-size=\"13\" fill=\"#2C3548\">2 000 × 41 %</text><text x=\"502\" y=\"194\" font-size=\"13\" fill=\"#2C3548\">+ 4 000 × 30 %</text><text x=\"502\" y=\"218\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">environ 2 020 €</text><text x=\"502\" y=\"238\" font-size=\"13\" fill=\"#8A95A8\">et non 2 460 €</text><rect x=\"12\" y=\"302\" width=\"616\" height=\"50\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\"/><text x=\"320\" y=\"323\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#162443\">Économie ≈ versement × TMI, tant qu’il reste dans la tranche</text><text x=\"320\" y=\"343\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Dire « environ » et confirmer au simulateur officiel : les seuils changent chaque année.</text></svg>","legende":"L’économie d’une déduction vaut environ le versement multiplié par la TMI, tant que le versement reste dans la tranche. Ce qui passe sous le seuil n’économise que le taux de la tranche du dessous."}]$academy_deck$::jsonb;
  select coalesce(jsonb_agg(s), '[]'::jsonb) into v_conserves
    from jsonb_array_elements(coalesce((select schemas from public.academy_module_versions where id = v_ver), '[]'::jsonb)) s
   where not exists (select 1 from jsonb_array_elements(v_nouveaux) x where x ->> 'cle' = s ->> 'cle');
  update public.academy_module_versions set schemas = v_conserves || v_nouveaux, updated_at = now() where id = v_ver;
  -- Figures : posee sur l exercice existant (ordre, type) qui n en a pas ; au dela du maximum, exercice nouveau.
  select coalesce(max(ordre), 0) into v_max from public.academy_items where version_id = v_ver;
  if v_max >= 4 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"tranche_marginale"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 4 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 4, $academy_deck$choix$academy_deck$, $academy_deck$Effet réel selon la TMI$academy_deck$, 1, $academy_deck${"enonce":"Qu'est-ce que la tranche marginale d'imposition (TMI) ?","choix":["Le taux de la dernière tranche atteinte par le revenu imposable du client","Le taux moyen payé sur l'ensemble des revenus du client","Le taux appliqué au plafonnement global des avantages fiscaux","Le taux de la tranche la plus élevée du barème, soit 45 %"],"figure":{"ref":"tranche_marginale"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":0}$academy_deck$::jsonb, $academy_deck$La TMI est le taux de la dernière tranche atteinte ; c'est lui qui mesure l'effet d'une déduction.$academy_deck$);
  end if;
  if v_max >= 30 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"colonne_impot"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 30 and type = $academy_deck$trou_choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 30, $academy_deck$trou_choix$academy_deck$, $academy_deck$Trois mécanismes fiscaux$academy_deck$, 1, $academy_deck${"phrase":"Une réduction d'impôt ne profite qu'à un client ___.","choix":["imposable","non imposable","en tranche à 45 %","titulaire d'un PER"],"figure":{"ref":"colonne_impot"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":0}$academy_deck$::jsonb, $academy_deck$Sans impôt dû, une réduction ne produit rien et ne se rembourse pas.$academy_deck$);
  end if;
  if v_max >= 41 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"colonne_impot"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 41 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 41, $academy_deck$choix$academy_deck$, $academy_deck$Trois mécanismes fiscaux$academy_deck$, 1, $academy_deck${"enonce":"Sur le schéma, à quel endroit de la colonne intervient la déduction ?","choix":["Entre le revenu déclaré et le revenu imposable","Entre le revenu imposable et l’impôt calculé","Entre l’impôt calculé et l’impôt à payer","Après l’impôt à payer, au moment du remboursement"],"figure":{"ref":"colonne_impot"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":0}$academy_deck$::jsonb, $academy_deck$Sur le schéma, la déduction est retirée avant le barème : c’est un revenu diminué qui passe au calcul. Réduction et crédit, eux, viennent après, sur l’impôt calculé.$academy_deck$);
  end if;
  if v_max >= 42 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"colonne_impot"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 42 and type = $academy_deck$multi$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 42, $academy_deck$multi$academy_deck$, $academy_deck$Trois mécanismes fiscaux$academy_deck$, 2, $academy_deck${"enonce":"Sur le schéma, le barème progressif occupe l’encadré du milieu. Cochez tout ce qui est exact à son sujet.","choix":["Il porte sur le revenu imposable, une fois la déduction retirée","Il produit l’impôt calculé, avant toute réduction et tout crédit","Ses taux sont 0, 11, 30, 41 et 45 %, tranche par tranche","Il s’applique à l’impôt à payer, une fois les crédits imputés","Il retire du revenu déclaré les réductions d’impôt"],"figure":{"ref":"colonne_impot"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"indices":[0,1,2]}$academy_deck$::jsonb, $academy_deck$Le barème vient après la déduction et avant les réductions et crédits : il transforme le revenu imposable en impôt calculé, tranche par tranche.$academy_deck$);
  end if;
  if v_max >= 43 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"tranche_marginale"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 43 and type = $academy_deck$trou_choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 43, $academy_deck$trou_choix$academy_deck$, $academy_deck$Effet réel selon la TMI$academy_deck$, 2, $academy_deck${"phrase":"Sur le schéma, dans le cas 2, la part du versement qui passe sous le seuil de la tranche à 41 % n’économise que ___.","choix":["30 %","41 %","11 %","45 %"],"figure":{"ref":"tranche_marginale"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":0}$academy_deck$::jsonb, $academy_deck$Seule la part du versement située dans la tranche marginale économise son taux ; le reste retombe à la tranche du dessous, ici 30 %.$academy_deck$);
  end if;
end
$schemas_fiscalite_raisonner$;
